// Private finite-Omega Einstein-coordinate point gate. No spatial operator.
#include "binding/baseline_dual_spatial.hpp"
#include "binding/generic_gauge.hpp"
#include "binding/native_injection.hpp"
#undef InteriorLayerGauge
#undef AssembleGaugeInterior
#include "coordinate_lift.hpp"
#include <string>
#include <vector>
using Raw=std::array<double,22>;
constexpr int ti[6]={0,0,0,1,1,2},tj[6]={0,1,2,1,2,2};
double Norm(const Raw&a){double v=0;for(double x:a)v+=x*x;return std::sqrt(v);}
double Max(const Raw&a){double v=0;for(double x:a)v=std::max(v,std::abs(x));return v;}
Raw Difference(const Raw&a,const Raw&b){Raw c{};for(int i=0;i<22;++i)c[i]=a[i]-b[i];return c;}
#include "actual_binding.hpp"

template<int N> double Deriv(const Poly<N>&p,int i){return Partial(p,i).value();}
template<int N> double Deriv2(const Poly<N>&p,int i,int j){return Partial(Partial(p,i),j).value();}
template<int N> void SetScalar(hyp::ScalarJet<double>&s,const Poly<N>&v){s.value=v.value();for(int i=0;i<3;++i){if constexpr(N>=1)s.d[i]=Deriv(v,i);for(int j=0;j<3;++j)if constexpr(N>=2)s.dd[i][j]=Deriv2(v,i,j);}}
template<int N> J NativePoly(const Poly<N>&a,double scale,bool dual){J v(dual?D(0,a.value()):D(scale*a.value()));for(int i=0;i<3;++i){if constexpr(N>=1)v.d[i]=dual?D(0,Deriv(a,i)):D(scale*Deriv(a,i));for(int j=0;j<3;++j)if constexpr(N>=2)v.dd[i][j]=dual?D(0,Deriv2(a,i,j)):D(scale*Deriv2(a,i,j));}return v;}
hyp::LayerPoint<double> CompletePoint(const CPoint&x,const CoordinateBackground&b){
 hyp::LayerReference<double>old(1.,.5,{true,.05,.95});auto p=old.At(x[0],x[1],x[2]);
 // Only metadata not consumed by source-off C0 gauge retains the old values.
 p.alpha=b.alpha.value();p.omega=b.omega.value();p.k_physical=b.P.value();
 SetScalar(p.state.alpha,b.alpha);SetScalar(p.state.chi,b.chi);SetScalar(p.state.trace,b.P);p.state.theta={};
 const auto gi=MatrixInv(b.g);PVector<2>lambda{};for(int i=0;i<3;++i)for(int j=0;j<3;++j)lambda[i]-=Partial(gi[i][j],j);
 for(int i=0;i<3;++i){p.beta[i]=b.beta[i].value();p.dalpha[i]=Deriv(b.alpha,i);p.domega[i]=Deriv(b.omega,i);p.state.beta.value[i]=b.beta[i].value();p.state.lambda.value[i]=lambda[i].value();
  for(int d=0;d<3;++d){p.omega_hessian[i][d]=Deriv2(b.omega,i,d);p.state.beta.d[d][i]=Deriv(b.beta[i],d);p.state.lambda.d[d][i]=Deriv(lambda[i],d);for(int e=0;e<3;++e){p.state.beta.dd[d][e][i]=Deriv2(b.beta[i],d,e);p.state.lambda.dd[d][e][i]=Deriv2(lambda[i],d,e);}}
  for(int j=0;j<3;++j){p.state.metric.g[i][j]=b.g[i][j].value();p.state.a.k[i][j]=b.A[i][j].value();for(int d=0;d<3;++d){p.state.metric.dg[d][i][j]=Deriv(b.g[i][j],d);p.state.a.dk[d][i][j]=Deriv(b.A[i][j],d);for(int e=0;e<3;++e)p.state.metric.ddg[d][e][i][j]=Deriv2(b.g[i][j],d,e);}}
 }
 return p;
}
Jet LiftCoordinate(const hyp::LayerPoint<double>&p,const CoordinateLift&v,double scale=0,bool dual=true){
 Jet u=Lift(p.state);Scalar(u.alpha,NativePoly(v.alpha,scale,dual));Scalar(u.chi,NativePoly(v.chi,scale,dual));Scalar(u.trace,NativePoly(v.P,scale,dual));
 for(int i=0;i<3;++i){Vector(u.beta,i,NativePoly(v.beta[i],scale,dual));Vector(u.lambda,i,NativePoly(v.lambda[i],scale,dual));for(int j=i;j<3;++j){SetMetric(u,i,j,Metric(u,i,j)+NativePoly(v.g[i][j],scale,dual));SetA(u,i,j,A(u,i,j)+NativePoly(v.A[i][j],scale,dual));}}return u;
}
Raw LiftValues(const CoordinateLift&v){Raw a{};a[0]=v.chi.value();a[7]=v.P.value();a[18]=v.alpha.value();for(int s=0;s<6;++s){a[1+s]=v.g[ti[s]][tj[s]].value();a[8+s]=v.A[ti[s]][tj[s]].value();}for(int i=0;i<3;++i){a[14+i]=v.lambda[i].value();a[19+i]=v.beta[i].value();}return a;}
double JetScale(const Jet&u){double s=1;for(auto v:Values(u,true))s=std::max(s,std::abs(v));for(int i=0;i<3;++i){s=std::max({s,std::abs(u.alpha.d[i].d),std::abs(u.chi.d[i].d),std::abs(u.trace.d[i].d)});for(int j=0;j<3;++j){s=std::max({s,std::abs(u.beta.d[i][j].d),std::abs(u.lambda.d[i][j].d)});for(int k=0;k<3;++k){s=std::max({s,std::abs(u.metric.dg[k][i][j].d),std::abs(u.a.dk[k][i][j].d)});for(int l=0;l<3;++l)s=std::max(s,std::abs(u.metric.ddg[k][l][i][j].d));}}}return s;}
std::array<double,4> LinearGauge(const hyp::LayerPoint<double>&p,const CoordinateBackground&b,const CoordinateLift&v){
 hyp::LayerGaugeParameters g;g.physical_trace_lapse=true;g.preferred_source=false;g.scri_lapse_damping=2;
 const double alpha=b.alpha.value(),chi=b.chi.value(),W=hyp::LayerCoefficients(p.radius,alpha,g).weight,e=1-W,mu=3*e/8+W,nu=1.5*W;
 const auto gi=MatrixInv(b.g);std::array<double,4>f{};double q=0,ghat=0,deltaG=0;
 for(int i=0;i<3;++i){f[0]+=b.beta[i].value()*Deriv(v.alpha,i)+v.beta[i].value()*Deriv(b.alpha,i);q+=p.domega[i]*p.domega[i];for(int j=0;j<3;++j){double dg=v.chi.value()*gi[i][j].value();for(int k=0;k<3;++k)for(int l=0;l<3;++l)dg-=chi*gi[i][k].value()*v.g[k][l].value()*gi[l][j].value();ghat+=chi*gi[i][j].value()*p.domega[i]*p.domega[j];deltaG+=dg*p.domega[i]*p.domega[j];}}
 f[0]-=nu*v.alpha.value()+((alpha*alpha+2*e*alpha)*v.P.value()+4*W*alpha*v.alpha.value())/p.omega;
 for(int j=0;j<3;++j)f[0]-=W*(alpha*v.beta[j].value()+b.beta[j].value()*v.alpha.value())*p.domega[j]/p.omega;
 for(int i=0;i<3;++i){f[1+i]=mu*alpha*alpha*chi*v.lambda[i].value()-W*v.beta[i].value();for(int j=0;j<3;++j){f[1+i]+=b.beta[j].value()*Deriv(v.beta[i],j)+v.beta[j].value()*Deriv(b.beta[i],j);f[1+i]+=alpha*alpha*chi*gi[i][j].value()*(W/2*(Deriv(v.chi,j)/chi-v.chi.value()*Deriv(b.chi,j)/(chi*chi))-W*(Deriv(v.alpha,j)/alpha-v.alpha.value()*Deriv(b.alpha,j)/(alpha*alpha)));}
  if(W>0)f[1+i]-=6*W*(v.beta[i].value()-(2./3)*p.domega[i]*deltaG/(std::sqrt(q)*ghat))/p.omega;
 }return f;
}
std::array<double,4> Accelerations(const CoordinateBackground&b,const Coordinates&z,const std::array<double,4>&f){
 const auto bi=MatrixInv(b.bar);std::array<double,4>a{};a[0]=f[0]/b.alpha.value();double betaDTdot=0;for(int j=0;j<3;++j){betaDTdot+=b.beta[j].value()*Deriv(z.Tdot,j);a[0]+=b.beta[j].value()*Deriv(z.Tdot,j)-z.Xdot[j].value()*Deriv(b.a_phys,j)/b.a_phys.value();}
 for(int i=0;i<3;++i){a[1+i]=f[1+i]-b.beta[i].value()*(a[0]-betaDTdot);for(int j=0;j<3;++j)a[1+i]+=-z.Xdot[j].value()*Deriv(b.beta[i],j)+b.beta[j].value()*Deriv(z.Xdot[i],j)+b.alpha.value()*b.alpha.value()*bi[i][j].value()*Deriv(z.Tdot,j);}return a;
}
CoordinateLift CoreOracle(const CPoint&point,const std::array<std::array<double,4>,4>&c){
 const auto z=CoordinatePolynomial(point,c);std::array<C3,3>x;C3 rho;for(int i=0;i<3;++i){x[i]=CartesianVariable<3>(point[i],i);rho+=x[i]*x[i];}
 auto dr=[&](int f,int n){std::array<double,4>d{};for(int k=n;k<4;++k){d[k-n]=c[f][k];for(int j=0;j<n;++j)d[k-n]*=(k-j);}return RhoPolynomial(rho,d);};
 const C3 zeta=dr(1,0),zr=dr(1,1),zrr=dr(1,2),tr=dr(0,1),trr=dr(0,2),w=dr(3,0);CoordinateLift v{};
 v.alpha=Cut<2>(z.Tdot);v.chi=Cut<2>(-C3(2)*zeta-C3(4./3)*rho*zr);v.P=Cut<1>(-C3(6)*tr-C3(4)*rho*trr);
 for(int i=0;i<3;++i){v.beta[i]=Cut<2>(x[i]*(w-C3(2)*tr));v.lambda[i]=Cut<1>(C3(8./3)*x[i]*(C3(5)*zr+C3(2)*rho*zrr));for(int j=0;j<3;++j){const auto S=x[i]*x[j]-C3(i==j?1./3:0.)*rho;v.hbar[i][j]=Cut<2>(C3(i==j?2:0)*zeta+C3(4)*zr*x[i]*x[j]);v.g[i][j]=Cut<2>(C3(4)*zr*S);v.A[i][j]=Cut<1>(-C3(4)*trr*S);}}return v;
}
template<int N> double PolyError(const Poly<N>&a,const Poly<N>&b){double v=0;for(int i=0;i<=N;++i)for(int j=0;j<=N-i;++j)for(int k=0;k<=N-i-j;++k)v=std::max(v,std::abs(a(i,j,k)-b(i,j,k))/std::max(1.,std::abs(b(i,j,k))));return v;}
double LiftError(const CoordinateLift&a,const CoordinateLift&b){double v=std::max({PolyError(a.alpha,b.alpha),PolyError(a.chi,b.chi),PolyError(a.P,b.P)});for(int i=0;i<3;++i){v=std::max({v,PolyError(a.beta[i],b.beta[i]),PolyError(a.lambda[i],b.lambda[i])});for(int j=0;j<3;++j)v=std::max({v,PolyError(a.g[i][j],b.g[i][j]),PolyError(a.A[i][j],b.A[i][j])});}return v;}
std::array<double,4> CoreAcceleration(const CPoint&x,const std::array<std::array<double,4>,4>&c){double rho=0;for(double a:x)rho+=a*a;auto der=[&](int f,int n){double v=0;for(int k=n;k<4;++k){double a=c[f][k];for(int j=0;j<n;++j)a*=k-j;v+=a*std::pow(rho,k-n);}return v;};std::array<double,4>a{18*der(0,1)+12*rho*der(0,2),0,0,0};for(int i=0;i<3;++i)a[1+i]=x[i]*(2*der(2,1)+5*der(1,1)+2*rho*der(1,2));return a;}
double SpatialNormals(const CoordinateBackground&b,const CoordinateLift&v){const auto gi=MatrixInv(CutMatrix<2>(b.g));C2 det;C1 trace;for(int i=0;i<3;++i)for(int j=0;j<3;++j){det+=gi[i][j]*v.g[i][j];trace+=Cut<1>(gi[i][j])*v.A[i][j];for(int k=0;k<3;++k)for(int l=0;l<3;++l)trace-=Cut<1>(gi[i][k]*gi[j][l]*Cut<2>(b.A[k][l])*v.g[i][j]);}return std::max(PolyError(det,C2{}),PolyError(trace,C1{}));}
template<std::size_t N>void PrintArray(const std::array<double,N>&a){std::cout<<'[';for(std::size_t i=0;i<N;++i){if(i)std::cout<<',';if(!std::isfinite(a[i]))throw std::runtime_error("nonfinite output");std::cout<<a[i];}std::cout<<']';}
void Batch(){CPoint x;std::array<std::array<double,4>,4>c;while(std::cin>>x[0]>>x[1]>>x[2]){for(auto&row:c)for(auto&a:row)if(!(std::cin>>a))throw std::runtime_error("truncated coordinate coefficients");const auto b=CoordinateReference(x);const auto p=CompletePoint(x,b);if(!(p.omega>0))throw std::runtime_error("noninterior point");const auto z=CoordinatePolynomial(x,c);const auto v=EinsteinLift(b,z);const auto u=LiftCoordinate(p,v);const auto rhs=Derivative(ActualDual(p,u));Coordinates velocity{};velocity.T=z.Tdot;velocity.X=z.Xdot;auto expected=LiftValues(EinsteinLift(b,velocity));const auto gauge=LinearGauge(p,b,v);const auto accel=Accelerations(b,z,gauge);expected[18]=rhs[18];for(int i=0;i<3;++i)expected[19+i]=rhs[19+i];
 const auto normals=InputNormals(p,u),outnormals=OutputNormals(p,rhs);const auto q=Constraints(u,p);const auto base=Lift(p.state);const auto baseq=hyp::EvolvedConstraints(base,Omega(base,p));std::array<double,8>q0{baseq.hamiltonian.v,baseq.momentum[0].v,baseq.momentum[1].v,baseq.momentum[2].v,baseq.z4.z_covector[0].v,baseq.z4.z_covector[1].v,baseq.z4.z_covector[2].v,baseq.z4.theta_physical.v};
 std::array<double,4>actualgauge{rhs[18],rhs[19],rhs[20],rhs[21]};std::array<double,5>fd{};int eidx=0;for(double eps:{1e-4,3e-5,1e-5,3e-6,1e-6}){const auto plus=ActualDouble(p,LiftCoordinate(p,v,eps,false)),minus=ActualDouble(p,LiftCoordinate(p,v,-eps,false));Raw derivative{};for(int i=0;i<22;++i)derivative[i]=(plus[i]-minus[i])/(2*eps);fd[eidx++]=Norm(Difference(derivative,rhs))/std::max(1.,Norm(rhs));}
 std::cout<<"{\"point\":";PrintArray(x);std::cout<<",\"input22\":";PrintArray(Values(u,true));std::cout<<",\"actual_rhs22\":";PrintArray(rhs);std::cout<<",\"kinematic_geometry22\":";PrintArray(expected);std::cout<<",\"physical_constraints8\":";PrintArray(q);std::cout<<",\"reference_constraints8\":";PrintArray(q0);std::cout<<",\"input_normals\":";PrintArray(normals);std::cout<<",\"output_normals\":";PrintArray(outnormals);std::cout<<",\"gauge_attribution4\":";PrintArray(gauge);std::cout<<",\"actual_gauge4\":";PrintArray(actualgauge);std::cout<<",\"acceleration4\":";PrintArray(accel);std::cout<<",\"core_acceleration4\":";PrintArray(CoreAcceleration(x,c));std::cout<<",\"double_fd_errors\":";PrintArray(fd);std::cout<<",\"input_jet_scale\":"<<JetScale(u)<<",\"input_value_norm\":"<<Norm(Values(u,true))<<",\"rhs_norm\":"<<Norm(rhs)<<",\"reference_rhs_max\":"<<Max(Plain(ActualDual(p,base)))<<",\"spatial_normal_max\":"<<SpatialNormals(b,v)<<",\"core_lift_error\":"<<(p.radius<=.05?LiftError(v,CoreOracle(x,c)):0)<<"}\n";
}}
template<int N>void PrintPoly(const Poly<N>&a){std::cout<<'[';bool first=true;for(int i=0;i<=N;++i)for(int j=0;j<=N-i;++j)for(int k=0;k<=N-i-j;++k){if(!first)std::cout<<',';first=false;std::cout<<Ordinary(a,{i,j,k});}std::cout<<']';}
void ReferenceBatch(){CPoint x;while(std::cin>>x[0]>>x[1]>>x[2]){const auto b=CoordinateReference(x);std::cout<<"{\"point\":";PrintArray(x);std::cout<<",\"fields\":{";bool first=true;auto put=[&](const std::string&name,const auto&p){if(!first)std::cout<<',';first=false;std::cout<<'\"'<<name<<"\":";PrintPoly(p);};put("omega",b.omega);put("alpha",b.alpha);put("chi",b.chi);put("P",b.P);put("physical_lapse",b.a_phys);for(int i=0;i<3;++i){put("beta"+std::to_string(i),b.beta[i]);for(int j=0;j<3;++j){const auto ij=std::to_string(i)+std::to_string(j);put("g"+ij,b.g[i][j]);put("bar"+ij,b.bar[i][j]);put("physical"+ij,b.physical[i][j]);put("A"+ij,b.A[i][j]);put("K"+ij,b.K[i][j]);}}std::cout<<"}}\n";}}
Jet BindingState(const hyp::LayerPoint<double>&p,double finite,int col,double scale,bool dual,bool chart){Jet u=Lift(p.state);for(int c=0;c<20;++c){J z(D(finite*std::sin(c+1.)));for(int i=0;i<3;++i){z.d[i]=finite*std::cos((c+1.)*(i+1.))/3;for(int j=0;j<3;++j)z.dd[i][j]=finite*std::sin((c+1.)*(i+j+2.))/5;}Seed(u,c,z);}Consistent(u);J s(dual?D(0,1):D(scale));for(int i=0;i<3;++i){s.d[i]=dual?D(0,.13*(i+1)):D(scale*.13*(i+1));for(int j=0;j<3;++j)s.dd[i][j]=dual?D(0,.07*(i+j+1)):D(scale*.07*(i+j+1));}if(chart){Seed(u,col,s);Consistent(u);}else{if(col==0)Scalar(u.chi,s);if(col==7)Scalar(u.trace,s);if(col==17)Scalar(u.theta,s);if(col==18)Scalar(u.alpha,s);if(col>=1&&col<=6)SetMetric(u,ti[col-1],tj[col-1],Metric(u,ti[col-1],tj[col-1])+s);if(col>=8&&col<=13)SetA(u,ti[col-8],tj[col-8],A(u,ti[col-8],tj[col-8])+s);if(col>=14&&col<=16)Vector(u.lambda,col-14,s);if(col>=19)Vector(u.beta,col-19,s);}return u;}
void BindingGate(){const CPoint n{.36,-.48,.8};for(double r:{.025,.3,.6,.9,.98})for(double finite:{0.,.003})for(bool chart:{false,true}){const CPoint x{r*n[0],r*n[1],r*n[2]};const auto b=CoordinateReference(x);const auto p=CompletePoint(x,b);for(int col=0;col<(chart?20:22);++col){const auto u=BindingState(p,finite,col,0,true,chart);const auto exact=Derivative(ActualDual(p,u));std::array<double,5>errors{};int idx=0;for(double eps:{1e-4,3e-5,1e-5,3e-6,1e-6}){const auto plus=ActualDouble(p,BindingState(p,finite,col,eps,false,chart)),minus=ActualDouble(p,BindingState(p,finite,col,-eps,false,chart));Raw fd{};for(int i=0;i<22;++i)fd[i]=(plus[i]-minus[i])/(2*eps);errors[idx++]=Norm(Difference(fd,exact))/std::max(1.,Norm(exact));}std::cout<<"{\"radius\":"<<r<<",\"finite\":"<<finite<<",\"chart20\":"<<(chart?"true":"false")<<",\"column\":"<<col<<",\"fd_errors\":";PrintArray(errors);std::cout<<"}\n";}}
 const CPoint x{.9,0,0};const auto b=CoordinateReference(x);const auto p=CompletePoint(x,b);const auto u=BindingState(p,0,4,0,true,true);const auto good=GenericGauge(Reference(p),u,.5,true);hyp::LayerGaugeParameters g;g.physical_trace_lapse=true;g.preferred_source=false;g.scri_lapse_damping=2;hyp::GaugeRHS<D>bad{};hyp::ResearchNativeSpatialAssemble(hyp::ResearchNativeSpatialGauge(Reference(p),u,g),D(p.omega),bad);double delta=0;for(int i=0;i<3;++i)delta=std::max(delta,std::abs(good.beta[i].d-bad.beta[i].d));std::cout<<"{\"negative_double_only_wrapper_difference\":"<<delta<<"}\n";
}
void Synthetic(){const CPoint point{.2,-.3,.4};std::array<C3,3>x;C3 rho;for(int i=0;i<3;++i){x[i]=CartesianVariable<3>(point[i],i);rho+=x[i]*x[i];}const C3 f=rho*rho*rho;double derivative=0;for(int i=0;i<3;++i)derivative=std::max(derivative,std::abs(Deriv(f,i)-6*point[i]*rho.value()*rho.value()));const auto unit=(C3(1)+f)*Reciprocal(C3(1)+f);const double inv=PolyError(unit,C3(1));const auto r=CartesianPower(rho,.5);Taylor<3>radial;radial[0]=std::pow(r.value(),6);radial[1]=6*std::pow(r.value(),5);radial[2]=15*std::pow(r.value(),4);radial[3]=20*std::pow(r.value(),3);const double composition=PolyError(ComposeRadial(radial,r,r.value()),f);PMatrix<3>g{};for(int i=0;i<3;++i)for(int j=0;j<3;++j)g[i][j]=C3(i==j?1:0)+C3(.1)*x[i]*x[j];const auto gi=MatrixInv(g);double matrix=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j){C3 product;for(int k=0;k<3;++k)product+=g[i][k]*gi[k][j];matrix=std::max(matrix,PolyError(product,C3(i==j?1:0)));}std::cout<<"{\"derivative\":"<<derivative<<",\"reciprocal\":"<<inv<<",\"radial_composition\":"<<composition<<",\"matrix_inverse\":"<<matrix<<"}\n";}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{std::cout<<std::setprecision(17);if(argc!=2)throw std::runtime_error("mode required");const std::string mode(argv[1]);if(mode=="--batch")Batch();else if(mode=="--reference")ReferenceBatch();else if(mode=="--binding")BindingGate();else if(mode=="--synthetic")Synthetic();else throw std::runtime_error("unknown mode");}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=1;}Kokkos::finalize();return code;}
